var RockForms=!0;document.addEventListener("htmx:beforeRequest",(e)=>{if(typeof Nette=="undefined")return;if(e.target.tagName!=="FORM")return;if(!Nette.validateForm(e.target))e.preventDefault();});(()=>{let htmxAdded=!1;"input,focusin".split(",").forEach((event)=>{document.addEventListener(event,(e)=>{if(htmxAdded)return;htmxAdded=!0;if(typeof htmx!=="undefined")return;let script=document.createElement("script");if(typeof htmxAssetUrl=="undefined"){script.src="/site/modules/RockForms/lib/htmx.min.js"}else script.src=htmxAssetUrl;document.head.appendChild(script)})})})();(()=>{"input,focusin".split(",").forEach((event)=>{document.addEventListener(event,(e)=>{let form=e.target.closest("form");if(!form)return;let input=form.querySelector('input[name="csrf"]');if(!input)return;if(form.classList.contains("csrf-loaded"))return;form.classList.add("csrf-loaded");input.value="loading";fetch("/rockforms-csrf/",{headers:{"X-Requested-With":"XMLHttpRequest",},}).then((response)=>response.text()).then((tokenValue)=>{input.value=tokenValue}).catch((error)=>{alert("Error fetching CSRF token");console.error(error);input.value=""})})});let resetCSRF=function(){document.querySelectorAll(".RockForm input[name=csrf]").forEach((input)=>{input.value="";input.closest(".RockForm").classList.remove("csrf-loaded")})};document.addEventListener("DOMContentLoaded",resetCSRF);document.addEventListener("htmx:afterSwap",resetCSRF)})()